// Generated by gstack /ship Step 7 (test coverage audit), pass 1.
//
// Value: protects=loadJobs classifies Harbor trials: no reward is infra with its exception, reward>=1 passes,
//   timeouts and budget stops stay graded, cost and budget stops come from the proxy's session rows, skill opens and
//   wall time from evaluator/, and a trial with no row reports its cost as missing;
//   fails_when=an ungraded trial counts as fail, or cost/arm/model/skill opens are read from the wrong place;
//   why_new=analysis.test.ts builds Trial objects by hand and never reads a job directory; seam=none;
//   no_claim=Harbor's real result.json schema (hand-written fixtures modeled on the reader)
import { afterAll, expect, test } from "bun:test";
import { mkdirSync, mkdtempSync, rmSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { dirname, join } from "node:path";
import { loadJobs, type SessionRow } from "../analysis/analyze.ts";

const root = mkdtempSync(join(tmpdir(), "laneb-jobs-"));
afterAll(() => rmSync(root, { recursive: true, force: true }));

const trial = (name: string, files: Record<string, unknown>) => {
  for (const [rel, value] of Object.entries(files)) {
    const p = join(root, "job", name, rel);
    mkdirSync(dirname(p), { recursive: true });
    writeFileSync(p, typeof value === "string" ? value : JSON.stringify(value));
  }
};
const config = (task: string, arm: string) => ({ task: { path: `/run/tasks/${task}` }, agent: { model_name: "anthropic/claude-haiku-5-5", kwargs: { arm, upstream_model: "claude-haiku-5-5" } } });

test("loadJobs classifies graded, timed-out, budget-stopped and infra trials from a job directory", () => {
  trial("a-pass", {
    "result.json": { trial_name: "a-pass", verifier_result: { rewards: { reward: 1 } } },
    "config.json": config("t1", "gstack"),
    "evaluator/laneb-summary.json": { wall_s: 12 },
    "evaluator/sdk-messages.jsonl": JSON.stringify({ type: "AssistantMessage", content: [{ name: "Skill", input: { skill: "/investigate" } }] }) + "\n",
  });
  trial("b-infra", {
    "result.json": { trial_name: "b-infra", exception_info: { exception_type: "DockerError", exception_message: "build failed" } },
    "config.json": config("t2", "none"),
  });
  trial("c-timeout", {
    "result.json": { trial_name: "c-timeout", verifier_result: { rewards: { reward: 0 } }, exception_info: { exception_type: "AgentTimeoutError", exception_message: "slow" } },
    "config.json": config("t3", "placebo"),
  });
  trial("d-first-reward", {
    "result.json": { trial_name: "d-first-reward", verifier_result: { rewards: { score: 1 } } },
    "config.json": config("t4", "none"),
  });
  writeFileSync(join(root, "job", "job.log"), "not a trial");

  const rows: SessionRow[] = [{ id: "s-a", trial: "a-pass__env", spent_micros: 2_500_000, ok_responses: 4, requests: 4, refused: 1, refused_budget: 1, opened_at: "2026-10-28T00:00:00Z", closed_at: "2026-10-28T00:10:00Z" }];
  const trials = loadJobs([join(root, "job")], rows).sort((x, y) => x.trialName.localeCompare(y.trialName));
  expect(trials.map((t) => t.trialName)).toEqual(["a-pass", "b-infra", "c-timeout", "d-first-reward"]);
  const [a, b, c, d] = trials;
  expect(a).toMatchObject({ task: "t1", arm: "gstack", model: "claude-haiku-5-5", outcome: "pass", reason: "session budget stop, graded", costUsd: 2.5, requests: 4, refused: 1, budgetStop: true, agentTimeout: false, wallS: 12, skillOpens: ["investigate"] });
  expect(b).toMatchObject({ task: "t2", outcome: "infra", reason: "DockerError: build failed", costUsd: null, skillOpens: [], wallS: null });
  expect(c).toMatchObject({ task: "t3", arm: "placebo", outcome: "fail", reason: "agent timeout, graded", agentTimeout: true, budgetStop: false });
  expect(d).toMatchObject({ task: "t4", outcome: "pass", reason: "graded" });
});

// Generated by gstack /ship Step 7 (test coverage audit) for #25, pass 1.
// Value: protects=the analyze.ts CLI refuses a config without proxy session files, and with them prints the no-reward
//   column and the drop sensitivity section; fails_when=the sessions check or the sensitivity rerun is removed, so cost
//   silently reads as missing or the preregistered alternative goes unreported; why_new=other tests call analyze() and
//   markdown() directly, never the CLI; seam=none; no_claim=Harbor's real result.json schema (hand-written fixtures)
test("the analyze CLI needs session files, and reports paid no-reward trials with a drop sensitivity", () => {
  const job = join(root, "cli-job");
  const put = (rel: string, value: unknown) => {
    mkdirSync(dirname(join(job, rel)), { recursive: true });
    writeFileSync(join(job, rel), JSON.stringify(value));
  };
  put("p__1/result.json", { trial_name: "p__1", verifier_result: { rewards: { reward: 1 } } });
  put("p__1/config.json", config("t1", "none"));
  put("q__1/result.json", { trial_name: "q__1", exception_info: { exception_type: "VerifierTimeoutError", exception_message: "slow" } });
  put("q__1/config.json", config("t2", "none"));
  const sessions = join(root, "cli-sessions.jsonl");
  const srow = (id: string, trial: string) => JSON.stringify({ id, trial: trial + "__env", spent_micros: 1_000_000, ok_responses: 2, requests: 2, refused: 0, refused_budget: 0, opened_at: "2026-10-28T00:00:00Z", closed_at: "2026-10-28T00:10:00Z" });
  writeFileSync(sessions, [srow("s-p", "p__1"), srow("s-q", "q__1")].join("\n") + "\n");
  const base = { models: ["claude-haiku-5-5"], arms: ["none"], reference: "claude-haiku-5-5", jobs: [job] };
  const cli = (cfg: unknown) => {
    const path = join(root, `cfg-${Math.random().toString(36).slice(2)}.json`);
    writeFileSync(path, JSON.stringify(cfg));
    return Bun.spawnSync(["bun", join(import.meta.dir, "../analysis/analyze.ts"), path]);
  };

  for (const cfg of [base, { ...base, sessions: [] }]) {
    const r = cli(cfg);
    expect(r.exitCode).toBe(2);
    expect(r.stderr.toString()).toStartWith("E_USAGE");
  }

  const r = cli({ ...base, sessions: [sessions] });
  const out = r.stdout.toString();
  expect(r.exitCode).toBe(0);
  expect(out).toContain("| claude-haiku-5-5 | none | 2 | 2 | 50% ");
  expect(out).toContain("| $2.00 | $2.00 |");
  expect(out).toContain("## Sensitivity: 1 paid trials without a verifier reward dropped");
  expect(out.split("## Sensitivity")[1]).toContain("| claude-haiku-5-5 | none | 1 | 1 | 100% ");
  const tail = JSON.parse(out.slice(out.lastIndexOf("\n{\n")));
  expect(tail.noReward.map((t: any) => t.trial)).toEqual(["q__1"]);
  expect(tail.costMissing).toEqual([]);
  expect(tail.infra).toEqual([]);
});
